template<typename T> struct List {};
template<typename T> struct Vec {};

// C++11/17 Right Angle Bracket Rule:
// In template argument context, '>>' is split into '>' '>'
Vec< List<int>> v;

// Context matters:
// Outside template arguments, '>>' is bit shift operator
int val = (10 >> 1);

// Comparison operator remains standard
if (val > 5) {}

// Example requiring multi-argument specialization
template<typename T, int N> struct Array {};

Array< List<float>, 5 > a;
// Space before '>' here is optional, but helps readability.
// Still parsed as template closure.
